const root = document.querySelector('#sponsor-app');
const categoryInfo = [
  ['self', '自分のこと', ['group', 'solo']], ['relationship', '恋愛・夫婦', ['group']],
  ['friends', '友人', ['group']], ['family', '家族', ['group']], ['work', '仕事', ['group']],
  ['sports', 'スポーツ', ['group']], ['first-meeting', 'はじめまして', ['group']],
  ['roleplay', 'ロールプレイ', ['group']], ['adult', '成人向け', ['group', 'solo']],
  ['game', 'ゲーム', ['group']], ['love', '恋愛のこと', ['solo']], ['school', '学校・部活', ['solo']]
];
const state = { authenticated:false, sets:[], editing:null, busy:false, error:'', dirty:false };
const esc = (value = '') => String(value).replace(/[&<>"']/g, (char) => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[char]));
const blankSet = () => ({ id:'', providerName:'', title:'', description:'', categories:[], audience:'group', cards:Array.from({ length:6 }, () => ({ text:'' })), status:'draft', endMessage:'', siteUrl:'', ctaLabel:'', isR18:false });
const statusLabel = (status) => ({ draft:'下書き', published:'公開中' }[status] || status || '');
const allowedCategories = (audience) => categoryInfo.filter(([, , audiences]) => audience === 'both' || audiences.includes(audience)).map(([id]) => id);
const safeSiteUrl = (value) => { if (!value) return ''; try { const url = new URL(value); if (url.protocol !== 'https:' || url.username || url.password) return ''; return url.href; } catch { return ''; } };

async function request(path, options = {}) {
  const response = await fetch(path, { credentials:'same-origin', ...options, headers:{ ...(options.body ? {'Content-Type':'application/json'} : {}), ...(options.headers || {}) } });
  let payload = null; try { payload = await response.json(); } catch { /* empty response */ }
  if (!response.ok) { const error = new Error(payload?.error || 'request_failed'); error.status = response.status; throw error; }
  return payload;
}
function normalize(input = {}) { return { ...blankSet(), ...input, categories:Array.isArray(input.categories) ? input.categories : [], cards:Array.isArray(input.cards) ? input.cards.map((card) => typeof card === 'string' ? { text:card } : { id:card?.id, text:String(card?.text || '') }) : [] }; }
function shell(body) { root.innerHTML = `<header class="sponsor-top"><a class="sponsor-brand" href="/admin.html" aria-label="Mingle.Cards 管理画面"><img src="/assets/mingle-cards-masthead.png" alt="Mingle.Cards" /></a><nav><a href="/admin.html">利用状況</a><a href="#" data-logout>ログアウト</a></nav></header>${body}`; root.querySelector('[data-logout]')?.addEventListener('click', logout); root.querySelector('[data-focus]')?.focus(); }
function login(message = '') { root.innerHTML = `<section class="login-view"><a class="sponsor-brand" href="/" aria-label="Mingle.Cards ホーム"><img src="/assets/mingle-cards-masthead.png" alt="Mingle.Cards" /></a><div class="login-card"><p class="eyebrow">ADMIN / SPONSOR CARDS</p><h1>スポンサー提供カード</h1><p class="muted">管理者パスワードでログインしてください。</p><form data-login><label class="field"><span>パスワード</span><input name="password" type="password" autocomplete="current-password" required /></label><p class="status">${esc(message)}</p><button class="button primary" type="submit">ログイン</button></form></div></section>`; root.querySelector('[data-login]').addEventListener('submit', async (event) => { event.preventDefault(); const form = event.currentTarget; const password = form.password.value; if (!password) return; try { await request('/api/admin/session', { method:'POST', body:JSON.stringify({ password }) }); state.authenticated = true; await load(); } catch (error) { form.querySelector('.status').textContent = error.status === 429 ? '試行回数が多すぎます。しばらく待ってください。' : 'ログインできませんでした。'; } }); }
async function logout(event) { event.preventDefault(); if (state.busy) return; await request('/api/admin/session', { method:'DELETE' }).catch(() => {}); state.authenticated = false; login(); }
async function stopSet(id) { if (state.busy) return; const set = state.sets.find((item) => String(item.id) === String(id)); if (!set) return; state.busy = true; state.error = ''; listView(); try { await request(`/api/admin/sponsors?id=${encodeURIComponent(id)}`, { method:'PATCH', body:JSON.stringify({ ...set, status:'draft' }) }); await load(); } catch { state.busy = false; state.error = '公開停止できませんでした。'; listView(); } }
function listView() { const rows = state.sets.length ? state.sets.map((set) => `<article class="set-row"><div><h3>${esc(set.title || '名称未設定')}</h3><p>${esc(set.providerName || '提供元未設定')} · ${set.cards?.length || 0}枚</p></div><div class="set-actions"><span class="set-status">${esc(statusLabel(set.status))}</span><button class="button subtle" data-edit="${esc(set.id)}" ${state.busy ? 'disabled' : ''}>編集</button>${set.status === 'published' ? `<button class="button subtle" data-stop="${esc(set.id)}" ${state.busy ? 'disabled' : ''}>公開停止</button>` : ''}</div></article>`).join('') : '<p class="empty">スポンサー提供カードはまだありません。</p>'; shell(`<main class="sponsor-main"><div class="sponsor-heading"><div><p class="eyebrow">ADMIN / SPONSOR CARDS</p><h1 data-focus>スポンサー提供カード</h1><p class="muted">公式提供者名とスポンサー表示を添えて、会話の時間をつくるカードを管理します。</p></div><div class="top-actions"><button class="button primary" data-new ${state.busy ? 'disabled' : ''}>新しく作る</button></div></div><p class="status">${esc(state.error)}</p><section class="panel"><h2>登録済みのカード</h2><div class="set-list">${rows}</div></section></main>`); root.querySelector('[data-new]')?.addEventListener('click', () => { state.editing = blankSet(); state.dirty = false; editor(); }); root.querySelectorAll('[data-edit]').forEach((button) => button.addEventListener('click', () => { state.editing = normalize(state.sets.find((set) => String(set.id) === button.dataset.edit)); state.dirty = false; editor(); })); root.querySelectorAll('[data-stop]').forEach((button) => button.addEventListener('click', () => stopSet(button.dataset.stop))); }
function preview(set) { const card = set.cards.find((item) => item.text.trim())?.text || 'ここにカードの内容が表示されます'; const href = safeSiteUrl(set.siteUrl); return `<aside class="panel"><h2>表示プレビュー</h2><p class="section-note">実際の表示に近い形で、スポンサー表示と終了後の案内を確認できます。</p><article class="preview-card"><section class="preview-catalog"><span class="sponsor-mark">スポンサー</span><h3>${esc(set.title || 'セット名')}</h3><p class="preview-provider">${esc(set.providerName || '提供元名')}の公式カード</p><p>${esc(set.description || 'セットの説明がここに表示されます。')}</p><div class="preview-question"><strong>${esc(card)}</strong></div></section></article><section class="preview-end-section"><h3>終了後の表示</h3><section class="preview-end"><strong>${esc(set.endMessage || '終了後メッセージがここに表示されます。')}</strong>${href ? `<a href="${esc(href)}" rel="noopener noreferrer">${esc(set.ctaLabel || 'スポンサーサイトを見る')}</a>` : ''}</section></section></aside>`; }
function editor() { const set = state.editing; const allowed = allowedCategories(set.audience); const categoryRows = categoryInfo.filter(([id]) => allowed.includes(id)).map(([id, label]) => `<label><input type="checkbox" name="category" value="${esc(id)}" ${set.categories.includes(id) ? 'checked' : ''} ${state.busy ? 'disabled' : ''}>${esc(label)}</label>`).join(''); const cards = set.cards.map((card, index) => `<div class="card-row"><span class="card-number">${index + 1}</span><textarea name="card" maxlength="300" required aria-label="${index + 1}枚目のカード" ${state.busy ? 'disabled' : ''}>${esc(card.text)}</textarea>${set.cards.length > 6 ? `<button type="button" class="remove-card" data-remove="${index}" ${state.busy ? 'disabled' : ''}>外す</button>` : '<span></span>'}</div>`).join(''); const published = set.status === 'published'; shell(`<main class="sponsor-main"><div class="sponsor-heading"><div><p class="eyebrow">ADMIN / SPONSOR CARDS</p><h1 data-focus>${set.id ? 'スポンサー提供カードを編集' : 'スポンサー提供カードを作る'}</h1><p class="muted">スポンサーであることを明示し、終了後に次の案内を表示できます。</p></div></div><p class="status">${esc(state.error)}</p><div class="editor-layout"><form class="panel" data-editor><h2>カードの設定</h2><p class="section-note">6〜40枚のカードを登録できます。公開前に表示プレビューで内容を確認してください。</p><div class="form-grid"><label class="field"><span>公式提供者名</span><input name="providerName" maxlength="80" value="${esc(set.providerName)}" placeholder="例：Mingle.Cards編集部" required ${state.busy ? 'disabled' : ''}><small>表示例：「Mingle.Cards編集部の公式カード」</small></label><label class="field"><span>セット名</span><input name="title" maxlength="120" value="${esc(set.title)}" placeholder="例：仕事の合間のひとこと" required ${state.busy ? 'disabled' : ''}></label><label class="field wide"><span>セットの内容</span><textarea name="description" maxlength="500" placeholder="どんな時間に使うカードかを書きます。" ${state.busy ? 'disabled' : ''}>${esc(set.description)}</textarea></label><fieldset class="field wide"><legend>対象カテゴリ</legend><div class="category-list">${categoryRows}</div></fieldset><fieldset class="field wide"><legend>対象</legend><div class="audience-list"><label><input type="radio" name="audience" value="group" ${set.audience === 'group' ? 'checked' : ''} ${state.busy ? 'disabled' : ''}>みんなで</label><label><input type="radio" name="audience" value="solo" ${set.audience === 'solo' ? 'checked' : ''} ${state.busy ? 'disabled' : ''}>ひとりで</label><label><input type="radio" name="audience" value="both" ${set.audience === 'both' ? 'checked' : ''} ${state.busy ? 'disabled' : ''}>どちらでも</label></div></fieldset><label class="check-field"><input type="checkbox" name="isR18" ${set.isR18 || set.categories.includes('adult') ? 'checked' : ''} ${set.categories.includes('adult') || state.busy ? 'disabled' : ''}>成人向け（R18）</label></div><h2>カード</h2><div class="card-list">${cards}</div><p class="count-note" data-count>${set.cards.length} / 40枚</p><button type="button" class="button subtle" data-add ${set.cards.length >= 40 || state.busy ? 'disabled' : ''}>カードを追加</button><h2>終了後の案内</h2><p class="section-note">最後のカードのあとに表示するメッセージと、スポンサーサイトへのリンクを設定します。</p><label class="field"><span>終了後メッセージ</span><textarea name="endMessage" maxlength="500" placeholder="例：この時間を応援してくれた〇〇からのお知らせです。" ${state.busy ? 'disabled' : ''}>${esc(set.endMessage)}</textarea></label><div class="form-grid"><label class="field"><span>スポンサーサイトURL（HTTPS）</span><input name="siteUrl" type="url" inputmode="url" placeholder="https://example.com" value="${esc(set.siteUrl)}" ${state.busy ? 'disabled' : ''}></label><label class="field"><span>リンク名</span><input name="ctaLabel" maxlength="40" value="${esc(set.ctaLabel)}" placeholder="スポンサーサイトを見る" ${state.busy ? 'disabled' : ''}></label></div><div class="form-actions"><button class="button primary" name="save" value="${published ? 'published' : 'draft'}" type="submit" ${state.busy ? 'disabled' : ''}>${published ? '公開内容を保存' : '下書き保存'}</button>${published ? '' : `<button class="button primary" name="save" value="published" type="submit" ${state.busy ? 'disabled' : ''}>公開する</button>`}<button class="button subtle" type="button" data-cancel ${state.busy ? 'disabled' : ''}>一覧へ戻る</button></div></form>${preview(set)}</div></main>`); bindEditor(); }
function readForm(form, statusOverride) { const data = new FormData(form); const audience = data.get('audience') || 'group'; const categories = data.getAll('category').filter((id) => allowedCategories(audience).includes(id)); return normalize({ ...state.editing, providerName:String(data.get('providerName') || '').trim(), title:String(data.get('title') || '').trim(), description:String(data.get('description') || '').trim(), categories, audience, cards:data.getAll('card').map((text, index) => ({ ...(state.editing.cards[index]?.id ? { id:state.editing.cards[index].id } : {}), text:String(text).trim() })), endMessage:String(data.get('endMessage') || '').trim(), siteUrl:String(data.get('siteUrl') || '').trim(), ctaLabel:String(data.get('ctaLabel') || '').trim(), isR18:data.get('isR18') === 'on' || categories.includes('adult'), status:statusOverride || state.editing.status }); }
function validate(set) { if (!set.providerName || !set.title || !set.description) return '提供者名、セット名、セットの内容を入力してください。'; if (Array.from(set.providerName).length > 80 || Array.from(set.title).length > 120 || Array.from(set.description).length > 500 || Array.from(set.endMessage).length > 500 || Array.from(set.ctaLabel).length > 40) return '入力できる文字数を超えています。'; if (!set.categories.length) return '対象カテゴリを1つ以上選んでください。'; if (!['group','solo','both'].includes(set.audience)) return '対象を選んでください。'; if (set.cards.length < 6 || set.cards.length > 40 || set.cards.some((card) => !card.text || Array.from(card.text).length > 300)) return 'カードは6〜40枚で、1枚300文字以内で入力してください。'; if (set.siteUrl && !safeSiteUrl(set.siteUrl)) return 'スポンサーサイトURLはHTTPSで入力してください。'; if (set.siteUrl && !set.ctaLabel) return 'サイトへのリンク名を入力してください。'; return ''; }
function bindEditor() { const form = root.querySelector('[data-editor]'); const markDirty = () => { state.dirty = true; }; form.querySelectorAll('input,textarea,select').forEach((input) => input.addEventListener('input', () => { markDirty(); state.editing = readForm(form); const count = root.querySelector('[data-count]'); if (count) count.textContent = `${state.editing.cards.length} / 40枚`; const target = root.querySelector('.editor-layout > .panel:last-child'); if (target) target.outerHTML = preview(state.editing); })); form.querySelectorAll('input[name="audience"]').forEach((input) => input.addEventListener('change', () => { state.editing = readForm(form); state.editing.categories = state.editing.categories.filter((id) => allowedCategories(state.editing.audience).includes(id)); editor(); state.dirty = true; })); root.querySelector('[data-add]')?.addEventListener('click', () => { if (state.editing.cards.length >= 40 || state.busy) return; state.editing = readForm(form); state.editing.cards.push({ text:'' }); editor(); state.dirty = true; requestAnimationFrame(() => root.querySelectorAll('textarea[name="card"]')[state.editing.cards.length - 1]?.focus()); }); root.querySelectorAll('[data-remove]').forEach((button) => button.addEventListener('click', () => { state.editing = readForm(form); state.editing.cards.splice(Number(button.dataset.remove), 1); editor(); state.dirty = true; })); root.querySelector('[data-cancel]')?.addEventListener('click', () => { if (state.dirty && !window.confirm('入力中の内容を破棄して一覧へ戻りますか？')) return; state.dirty = false; listView(); }); form.addEventListener('submit', async (event) => { event.preventDefault(); if (state.busy) return; const set = readForm(form, event.submitter?.value || 'draft'); const error = validate(set); if (error) { state.error = error; editor(); return; } state.busy = true; state.error = ''; editor(); try { const path = state.editing.id ? `/api/admin/sponsors?id=${encodeURIComponent(state.editing.id)}` : '/api/admin/sponsors'; const payload = await request(path, { method:state.editing.id ? 'PATCH' : 'POST', body:JSON.stringify(set) }); state.editing = normalize(payload.set || set); state.dirty = false; await load(); } catch (requestError) { state.error = requestError.status === 401 ? 'セッションの有効期限が切れました。' : '保存できませんでした。入力内容を確認してください。'; state.busy = false; editor(); } }); }
async function load() { state.busy = true; try { const payload = await request('/api/admin/sponsors'); state.sets = Array.isArray(payload?.sets) ? payload.sets.map(normalize) : []; state.authenticated = true; state.busy = false; listView(); } catch (error) { state.busy = false; if (error.status === 401) { state.authenticated = false; login(''); } else { state.error = 'スポンサー提供カードを読み込めませんでした。'; listView(); } } }
window.addEventListener('beforeunload', (event) => { if (state.dirty) { event.preventDefault(); event.returnValue = ''; } });
async function init() { try { await request('/api/admin/session'); await load(); } catch (error) { login(error.status === 503 ? '管理画面は現在利用できません。' : ''); } }
init();
